using Microsoft.Dynamics.AX.Framework.DocumentContract;

/// <summary>
/// designed from AVA
/// </summary>
class AVASrsReportPrintFromStream
{
    public  System.IO.MemoryStream      printStream;
    container                           packedPrintDestination;
    public  FileName                    printedFileName;



}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_stream">_stream</param>
void   new(System.IO.MemoryStream      _stream)
{
    printStream     = _stream;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_packedPrintDesctination">_packedPrintDesctination</param>
/// <returns>parmPackedPrintDestination</returns>
container parmPackedPrintDestination(container  _packedPrintDesctination = packedPrintDestination)
{
    packedPrintDestination  = _packedPrintDesctination;
    return packedPrintDestination;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_printedFileName">_printedFileName</param>
/// <returns>parmFileName</returns>
Filename    parmFileName(Filename   _printedFileName = printedFileName)
{
    printedFileName = _printedFileName;
    return printedFileName;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>PdfDocumentContract</returns>
PdfDocumentContract  createDocumentContract()
{
    Filename                fileName;

    fileName     = printedFileName            ? printedFileName            : 'defaultFileName';

    PdfDocumentContract PdfDocumentContract = DocumentContractFactory::Instance.Create(DocumentContractType::Pdf);
    pdfDocumentContract.Name                       = fileName;
    pdfDocumentContract.Contents                   = printStream.ToArray();
    pdfDocumentContract.TargetType                 = TargetType::Printer;
    pdfDocumentContract.Settings                   =  this.getSrsPrintDestinationSettings().printerPageSettings();
    PdfDocumentContract.ActivityID                 = newGuid();

    return PdfDocumentContract;
}

/// <summary>
/// designed from  AVA
/// </summary>
/// <returns>SRSPrintDestinationSettings</returns>
 SRSPrintDestinationSettings    getSrsPrintDestinationSettings()
 {
     SRSPrintDestinationSettings     destinationSettings;

     if (conLen(packedPrintDestination) != 0)
     {
         destinationSettings = new SRSPrintDestinationSettings(packedPrintDestination);   
     }
     else
     {
         destinationSettings = new SRSPrintDestinationSettings();
         destinationSettings.printMediumType(SRSPrintMediumType::Screen);
         destinationSettings.numberOfCopies(1);
         destinationSettings.collate(false);
         destinationSettings.printAllPages(true);
         destinationSettings.fromPage(0);
         destinationSettings.toPage(0);
     }       

     return destinationSettings;
 }

boolean check()
{
    boolean  ret = true;
    if (printStream == null)
    {
        ret = checkFailed("@NDX:NXANoPrintContent");
    }
    SRSPrintDestinationSettings     locPrintDestination =  new SRSPrintDestinationSettings(packedPrintDestination);
    if( locPrintDestination.printerName() == '' || locPrintDestination.printMediumType() != SRSPrintMediumType::Printer)
    {
        ret = checkFailed('@NDX:NXAPrintReferencePrinterError');
    }

    return ret;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_stream">_stream</param>
/// <param name = "_printSettings">_printSettings</param>
public static void printStream(System.IO.MemoryStream       _stream, Filename   _printedFileName, container      _printSettings = conNull())
{
    AVASrsReportPrintFromStream     reportPrintFromStream = new AVASrsReportPrintFromStream(_stream);
    if (conlen(_printSettings) != 0)
    {
        reportPrintFromStream.parmPackedPrintDestination(_printSettings);
    }

    reportPrintFromStream.parmFileName(_printedFileName);
    if (reportPrintFromStream.check())
    {
        reportPrintFromStream.printOut();
    }
}
